div.p:
- id: int {id}
- versionNo: int
- phase: Phase
- title: String
- abstract: Text
- originalFilename: String
- storedFilename: String {unique}
- sizeBytes: int {<= 20 MB, PDF only}
- sha256: String
- createdAt: DateTime

- id: int {id}
- body: Text
- createdAt: DateTime

- phase: Phase {id}
- dueAt: DateTime
- graceDays: int {0..7}
- penaltyPerDay: int {0..100 %}
- /closesAt: DateTime = dueAt + graceDays

+ status(now: DateTime): String {not_set | open | grace | closed}
+ lateDays(at: DateTime): int
+ dueSoon(days: int): Boolean
